"""Configuration: ~/.config/ai-delegate/config.yaml, with defaults for everything."""

from __future__ import annotations

import os
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

import yaml

from ai_delegate.bench import BenchConfig
from ai_delegate.web import WebConfig

CONFIG_PATH = Path(
    os.environ.get("AI_DELEGATE_CONFIG", "~/.config/ai-delegate/config.yaml")
).expanduser()
# Generated by `ai-delegate routes --write` from ai-bench results (M3).
ROUTES_PATH = CONFIG_PATH.with_name("routes.yaml")

# Ordered candidates per kind of work. M3 regenerates these from ai-bench results; until then
# they follow DESIGN.md: fast drafting on flint or nemotron-lightning, careful review on
# ThinkingCap. A name matches a model's id, name or alias, on any machine.
DEFAULT_ROUTES: dict[str, list[str]] = {
    "ask": ["flint", "deepseek-v4-flash", "nemotron-3.5-lightning-30b-a3b", "qwen3.8-27b"],
    "review": ["thinkingcap-qwen3.8-27b", "deepseek-v4-flash", "flint", "qwen3.8-27b"],
    # ai-factory's Builder binding: flint first.
    "delegate": ["flint", "deepseek-v4-flash", "qwen3.8-27b"],
    # Reading and reasoning over code: careful, then fast.
    "research": ["deepseek-v4-flash", "thinkingcap-qwen3.8-27b", "flint"],
    # Many small JSON steps (plan, read a page, write): fast models that follow instructions.
    "web_research": ["flint", "deepseek-v4-flash", "qwen3.8-27b"],
}
DEFAULT_TIMEOUTS: dict[str, float] = {"ask": 300.0, "review": 600.0}


@dataclass
class Jobs:
    """Delegated jobs (M2): the sandbox and the per-job budgets (as ai-factory's watchdog)."""

    # "docker"; "host": pi on the host under srt (sandbox-runtime), writes limited to the
    # clone and network to the gateway; "local": pi on the host in the clone, unisolated.
    sandbox: str = "docker"
    srt: str = "srt"  # the sandbox-runtime CLI, for sandbox "host"
    host_allow_write: list[str] = field(default_factory=list)  # extra writable paths (caches)
    host_deny_read: list[str] = field(default_factory=list)  # added to sandbox.HOST_DENY_READ
    image: str = "ai-factory/executor-base:latest"
    cpus: str = "4"
    memory: str = "8g"
    time_limit_s: float = 1800
    max_requests: int = 80
    max_tokens: int = 400_000  # new tokens: unseen prompt plus completions
    max_diff_lines: int = 800
    max_running: int = 2  # per machine with the daemon, per session without
    # Jobs run in a daemon per machine, so they outlive the session that started them; it
    # exits after this long with no job and no request (0: never). False: in each session's
    # own process, as before (jobs end with the session).
    daemon: bool = True
    daemon_idle_exit_s: float = 1800
    default_context: int = 131_072  # when ai-swap doesn't report a model's window


@dataclass
class ModelSettings:
    """Per-model request settings (config.yaml `models:`), for what ai-swap can't say."""

    # The context window, when ai-swap doesn't report one (oMLX models show "?").
    context: int | None = None
    # A thinking model's share of the output budget for reasoning, sent per request as
    # `thinking_budget` (oMLX forces </think> there). Without it a thinking model can spend
    # the whole budget reasoning and write no answer.
    thinking_budget: float | None = None
    # Extra fields merged into every chat request to this model.
    params: dict[str, Any] = field(default_factory=dict)


@dataclass
class Config:
    endpoint: str = "http://studio.local:8080"  # the first of endpoints
    # ai-swap addresses in order of preference, e.g. the LAN name, then its Tailscale name;
    # the first that answers is used, and a failed connection moves on to the next.
    endpoints: list[str] = field(default_factory=list)
    # ai-swap's API key, when it requires one (AI_SWAP_API_KEY, or `api_key` here). Sent on
    # every call to ai-swap and put on the sandboxed agent's requests by the job gateway.
    api_key: str = ""
    routes: dict[str, list[str]] = field(default_factory=lambda: dict(DEFAULT_ROUTES))
    timeouts: dict[str, float] = field(default_factory=lambda: dict(DEFAULT_TIMEOUTS))
    # A tool's own thinking budget share (e.g. review: thinking_budget: 0.375), used instead
    # of the model's for models that have one; a smaller share makes that tool answer sooner.
    tool_thinking: dict[str, float] = field(default_factory=dict)
    max_input_bytes: int = 400_000  # files and diffs sent with one call
    max_output_tokens: int = 32_768  # cap on a quarter of the model's context
    jobs: Jobs = field(default_factory=Jobs)
    bench: BenchConfig = field(default_factory=BenchConfig)
    web: WebConfig = field(default_factory=WebConfig)
    # Where each tool's list came from: "defaults", "ai-bench (<date>)" or "config.yaml".
    route_source: dict[str, str] = field(default_factory=dict)
    # Model name (as in a route: "flint", "flint@studio") -> its request settings.
    models: dict[str, ModelSettings] = field(default_factory=dict)
    scores: dict[str, dict[str, Any]] = field(default_factory=dict)
    source: str = "defaults"


def read_env_file(path: Path) -> dict[str, str]:
    """KEY=VALUE lines (comments and blanks ignored), as `keys/render` writes them."""
    out: dict[str, str] = {}
    if not path.is_file():
        return out
    for line in path.read_text().splitlines():
        line = line.strip()
        if not line or line.startswith("#") or "=" not in line:
            continue
        k, v = line.split("=", 1)
        out[k.strip()] = v.strip().strip("'\"")
    return out


def load(path: Path = CONFIG_PATH, routes_path: Path | None = None) -> Config:
    cfg = Config()
    cfg.route_source = {tool: "defaults" for tool in cfg.routes}
    routes_path = routes_path or path.with_name("routes.yaml")
    if routes_path.is_file():
        doc: dict[str, Any] = yaml.safe_load(routes_path.read_text()) or {}
        when = str(doc.get("generated", ""))[:10]
        for tool, names in (doc.get("routes") or {}).items():
            if names:
                cfg.routes[tool] = [str(n) for n in names]
                cfg.route_source[tool] = f"ai-bench ({when})"
        cfg.scores = doc.get("scores") or {}
    if path.is_file():
        raw: dict[str, Any] = yaml.safe_load(path.read_text()) or {}
        cfg.source = str(path)
        cfg.api_key = str(raw.get("api_key") or cfg.api_key)
        ep = raw.get("endpoint", cfg.endpoint)
        cfg.endpoints = [str(e) for e in ep] if isinstance(ep, list) else [str(ep)]
        for tool in ("ask", "review", "delegate", "research", "web_research"):
            section = raw.get(tool) or {}
            if "models" in section:
                cfg.routes[tool] = [str(m) for m in section["models"] or []]
                cfg.route_source[tool] = "config.yaml"
            if "timeout_s" in section:
                cfg.timeouts[tool] = float(section["timeout_s"])
            if section.get("thinking_budget") is not None:
                share = float(section["thinking_budget"])
                if not 0 < share < 1:
                    raise ValueError(f"{path}: {tool}.thinking_budget is a share between 0 and 1")
                cfg.tool_thinking[tool] = share
        cfg.max_input_bytes = int(raw.get("max_input_bytes", cfg.max_input_bytes))
        cfg.max_output_tokens = int(raw.get("max_output_tokens", cfg.max_output_tokens))
        for name, section in (raw.get("models") or {}).items():
            section = section or {}
            unknown = set(section) - set(ModelSettings.__dataclass_fields__)
            if unknown:
                raise ValueError(f"{path}: unknown setting(s) {sorted(unknown)} for model {name!r}")
            tb = section.get("thinking_budget")
            if tb is not None and not 0 < float(tb) < 1:
                raise ValueError(f"{path}: {name}.thinking_budget is a share between 0 and 1")
            cfg.models[str(name)] = ModelSettings(
                context=int(section["context"]) if section.get("context") else None,
                thinking_budget=float(tb) if tb is not None else None,
                params=dict(section.get("params") or {}),
            )
        for key, value in (raw.get("jobs") or {}).items():
            if key not in Jobs.__dataclass_fields__:
                raise ValueError(f"{path}: unknown jobs setting {key!r}")
            current = getattr(cfg.jobs, key)
            setattr(cfg.jobs, key, type(current)(value))
        for key, value in (raw.get("web") or {}).items():
            if key not in WebConfig.__dataclass_fields__:
                raise ValueError(f"{path}: unknown web setting {key!r}")
            if key == "search_url":
                value = [str(u) for u in value] if isinstance(value, list) else [str(value)]
            else:
                value = type(getattr(cfg.web, key))(value)
            setattr(cfg.web, key, value)
        for key, value in (raw.get("bench") or {}).items():
            if key not in BenchConfig.__dataclass_fields__:
                raise ValueError(f"{path}: unknown bench setting {key!r}")
            setattr(cfg.bench, key, value)
    # Keys: the env file next to config.yaml (rendered from 1Password by ai-tools'
    # keys/render; ai-delegate is started by Claude Code, so it can't rely on the shell's
    # environment), then the process environment, which wins.
    keys = read_env_file(path.with_name("env")) | {
        k: v for k in ("AI_SWAP_API_KEY", "AI_DELEGATE_SEARCH_TOKEN") if (v := os.environ.get(k))
    }
    if v := keys.get("AI_SWAP_API_KEY"):
        cfg.api_key = v
    if v := keys.get("AI_DELEGATE_SEARCH_TOKEN"):
        cfg.web.search_token = v
    if env := os.environ.get("AI_DELEGATE_ENDPOINT"):  # one URL, or several comma-separated
        cfg.endpoints = env.split(",")
    cfg.endpoints = [e.strip().rstrip("/") for e in cfg.endpoints or [cfg.endpoint] if e.strip()]
    if not cfg.endpoints:
        raise ValueError("endpoint is empty")
    cfg.endpoint = cfg.endpoints[0]
    return cfg


def settings_for(cfg: Config, matches: Any) -> ModelSettings:
    """The settings of the first `models:` entry a model matches (`matches` is its
    Model.matches), or none."""
    for name, settings in cfg.models.items():
        if matches(name):
            return settings
    return ModelSettings()
